  app.post("/api/auth/register", async (req: Request, res: Response) => {
    try {
      const { email, password, name } = req.body as any;

      if (!email || !password || !name) {
        return res.status(400).json({ error: "Email, password, and name are required" });
      }

      if (password.length < 8) {
        return res.status(400).json({ error: "Password must be at least 8 characters" });
      }

      const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
      if (!emailRegex.test(email)) {
        return res.status(400).json({ error: "Invalid email address" });
      }

      const existingUser = await storage.getUserByEmail(email.toLowerCase().trim());
      if (existingUser) {
        return res.status(409).json({ error: "An account with this email already exists" });
      }

      const passwordHash = await bcrypt.hash(password, 12);

      const user = await storage.createUser({
        email: email.toLowerCase().trim(),
        name: name.trim(),
        passwordHash,
        isDemo: false,
        appleId: null,
        avatarUrl: null,
        biometricEnabled: false,
        autoSyncEnabled: true,
        notificationsEnabled: true,
      });

      auditLog(req, "register", "user", user.id, { method: "email" });

      const tokens = await createAuthSession(user.id, req);
      const { passwordHash: _, ...safeUser } = user;
      res.json({ user: safeUser, accessToken: tokens.accessToken, refreshToken: tokens.refreshToken });
    } catch (error) {
      console.error("Registration error:", error);
      res.status(500).json({ error: "Failed to create account" });
    }
  });


  app.post("/api/auth/login", async (req: Request, res: Response) => {
    try {
      const { email, password } = req.body as any;

      if (!email || !password) {
        return res.status(400).json({ error: "Email and password are required" });
      }

      const normalizedEmail = email.toLowerCase().trim();

      // Reviewer shortcut: active in any environment when REVIEWER_EMAIL + REVIEWER_PASSWORD are set.
      // No !IS_PRODUCTION guard — the shortcut must work in production for Apple App Review.
      // Security: the block only executes when both env vars are non-empty, so it is a no-op
      // in deployments where those secrets are absent.
      const reviewerEmail = (process.env.REVIEWER_EMAIL || "").toLowerCase().trim();
      const reviewerPassword = (process.env.REVIEWER_PASSWORD || "").trim();
      const isReviewerLogin =
        reviewerEmail && reviewerPassword && normalizedEmail === reviewerEmail && password === reviewerPassword;

      if (isReviewerLogin) {
        let user = await storage.getUserByEmail(reviewerEmail);
        if (!user) {
          const passwordHash = await bcrypt.hash(reviewerPassword, 12);
          user = await storage.createUser({
            email: reviewerEmail,
            name: "App Reviewer",
            passwordHash,
            isDemo: false,
            appleId: null,
            avatarUrl: null,
            biometricEnabled: false,
            autoSyncEnabled: true,
            notificationsEnabled: true,
          });
        }
        await ensureReviewerDemoData(user.id);
        auditLog(req, "login", "user", user.id, { method: "email" });
        const tokens = await createAuthSession(user.id, req);
        const { passwordHash: _, ...safeUser } = user;
        return res.json({ user: safeUser, accessToken: tokens.accessToken, refreshToken: tokens.refreshToken });
      }

      const user = await storage.getUserByEmail(normalizedEmail);
      if (!user || !user.passwordHash) {
        return res.status(401).json({ error: "Invalid email or password" });
      }

      const isValid = await bcrypt.compare(password, user.passwordHash);
      if (!isValid) {
        return res.status(401).json({ error: "Invalid email or password" });
      }

      auditLog(req, "login", "user", user.id, { method: "email" });

      const tokens = await createAuthSession(user.id, req);
      const { passwordHash: _, ...safeUser } = user;
      res.json({ user: safeUser, accessToken: tokens.accessToken, refreshToken: tokens.refreshToken });
    } catch (error) {
      console.error("Login error:", error);
      res.status(500).json({ error: "Failed to sign in" });
    }
  });


