  app.post("/api/auth/google", async (req: Request, res: Response) => {
    try {
      const { credential } = req.body as any;

      if (!credential) {
        return res.status(400).json({ error: "Google credential is required" });
      }

      const ticket = await googleAuthClient.verifyIdToken({
        idToken: credential,
        audience: process.env.GOOGLE_CLIENT_ID,
      });
      const payload = ticket.getPayload();

      if (!payload || !payload.sub) {
        return res.status(401).json({ error: "Invalid Google token" });
      }

      const googleId = payload.sub;
      const email = payload.email || `google-${googleId}@tabula-medica.app`;
      const name = payload.name || "User";
      const avatarUrl = payload.picture || null;

      let user = await storage.getUserByGoogleId(googleId);

      if (!user) {
        const existingUser = await storage.getUserByEmail(email);
        if (existingUser) {
          user = await storage.updateUser(existingUser.id, { googleId });
        } else {
          user = await storage.createUser({
            email,
            googleId,
            name,
            avatarUrl,
            isDemo: false,
            appleId: null,
            biometricEnabled: false,
            autoSyncEnabled: true,
            notificationsEnabled: true,
          });
        }
      }

      if (!user) {
        return res.status(500).json({ error: "Failed to create or find user" });
      }

      auditLog(req, "login", "user", user.id, { method: "google" });

      const tokens = await createAuthSession(user.id, req);
      const { passwordHash: _, ...safeUser } = user;
      res.json({ success: true, user: safeUser, accessToken: tokens.accessToken, refreshToken: tokens.refreshToken });
    } catch (error) {
      console.error("Google auth error:", error);
      res.status(401).json({ error: "Invalid Google token" });
    }
  });

