  app.post("/api/users/verify-status", async (req: Request, res: Response) => {
    try {
      const { email, isVerified, provider } = req.body as any;
      const token = (req.headers as any).authorization?.split(" ")[1];

      if (!token || token !== process.env.INTERNAL_SYNC_TOKEN) {
        logger.warn("Unauthorized verify-status attempt", {
          category: "security",
          ip: req.ip,
        });
        return res.status(401).json({ error: "Unauthorized" });
      }

      if (!email) {
        return res.status(400).json({ error: "Email is required" });
      }

      const validProviders = ["idme", "clear"];
      if (provider && !validProviders.includes(provider)) {
        return res.status(400).json({ error: "Invalid verification provider" });
      }

      const user = await storage.getUserByEmail(email.toLowerCase().trim());
      if (!user) {
        return res.status(404).json({ error: "User not found" });
      }

      await db.update(users)
        .set({
          isVerified: isVerified === true,
          verificationProvider: provider || null,
          verifiedAt: isVerified ? new Date() : null,
          updatedAt: new Date(),
        })
        .where(eq(users.email, email.toLowerCase().trim()));

      logger.info("User verification status synced from Auth0", {
        category: "authentication",
        userId: user.id,
        provider,
        isVerified,
      });

      auditLog(req, "identity_verification_sync", "user", user.id, {
        provider,
        isVerified,
        source: "auth0_post_login",
      });

      res.status(200).json({ message: "Verification synced" });
    } catch (error) {
      logger.error("Verify-status sync failed", {
        category: "authentication",
        error: error instanceof Error ? error.message : String(error),
      });
      res.status(500).json({ error: "Verification sync failed" });
    }
  });

