  app.get("/api/fasten/callback", async (req: Request, res: Response) => {
    try {
      const { code, state, error: authError } = req.query as any;

      if (authError) {
        logger.warn("Fasten OAuth callback error", {
          category: "authentication",
          error: authError as string,
        });
        return res.redirect("/?fasten_error=" + encodeURIComponent(authError as string));
      }

      if (!code) {
        return res.status(400).json({ error: "Authorization code is required" });
      }

      const { exchangeAuthCode } = await import("../fasten-health-service");
      const result = await exchangeAuthCode(code as string, state as string);

      if (!result) {
        return res.redirect("/?fasten_error=token_exchange_failed");
      }

      logger.info("Fasten OAuth callback success", {
        category: "authentication",
        orgConnectionId: result.orgConnectionId,
      });

      const callbackUserId = getUserId(req);
      if (callbackUserId) {
        recordCallbackVerifiedId(result.orgConnectionId, callbackUserId);
        try {
          const existingDs = await db.select({ id: dataSources.id })
            .from(dataSources)
            .where(
              and(
                eq(dataSources.userId, callbackUserId),
                eq(dataSources.name, `Fasten Connect - ${result.orgConnectionId}`)
              )
            )
            .limit(1);
          if (existingDs.length === 0) {
            await db.insert(dataSources).values({
              userId: callbackUserId,
              name: `Fasten Connect - ${result.orgConnectionId}`,
              type: "fasten_connect",
              isConnected: true,
              lastSyncAt: new Date(),
            });
          }
        } catch (dsErr) {
          logger.warn("Fasten OAuth callback: failed to pre-create data source entry", {
            category: "api",
            error: dsErr instanceof Error ? dsErr.message : String(dsErr),
          });
        }
      } else {
        logger.warn("Fasten OAuth callback: no authenticated session; callback-verified binding skipped", {
          category: "security",
          orgConnectionId: result.orgConnectionId,
        });
      }

      auditLog(req, "fasten_oauth_callback", "data_source", result.orgConnectionId, {
        source: "fasten_connect",
        status: "connected",
      });

      res.redirect("/?fasten_connected=true&org_connection_id=" + encodeURIComponent(result.orgConnectionId));
    } catch (error) {
      logger.error("Fasten OAuth callback error", {
        category: "authentication",
        error: error instanceof Error ? error.message : String(error),
      });
      res.redirect("/?fasten_error=callback_failed");
    }
  });


