  app.post("/api/fasten/webhook", createWebhookAuthMiddleware("fasten_health"), async (req: Request, res: Response) => {
    try {
      const { handleWebhookEvent } = await import("../fasten-health-service");
      const { claimWebhookEvent, markEventProcessed, markEventFailed } = await import("../webhook-security-service");
      const payload = req.body as any;

      if (!payload || !payload.type || !payload.id) {
        return res.status(400).json({ error: "Invalid webhook payload" });
      }

      const eventId: string = payload.id;

      const { claimed, id: webhookDbId } = await claimWebhookEvent({
        source: "fasten_health",
        eventType: payload.type,
        aggregatorEventId: eventId,
        payload: { type: payload.type, api_mode: payload.api_mode, id: eventId },
      });

      if (!claimed) {
        logger.info("Fasten webhook duplicate delivery acknowledged", {
          category: "webhook",
          eventType: payload.type,
          eventId,
        });
        return res.status(200).json({ handled: true, message: "Duplicate event acknowledged" });
      }

      logger.info("Fasten webhook received", {
        category: "webhook",
        eventType: payload.type,
        eventId,
      });

      let resolvedUserId: string | undefined;
      const orgConnectionId: string | undefined = payload.data?.org_connection_id;
      if (orgConnectionId) {
        try {
          const sources = await db.select({ userId: dataSources.userId })
            .from(dataSources)
            .where(
              and(
                eq(dataSources.type, "fasten_connect"),
                eq(dataSources.name, `Fasten Connect - ${orgConnectionId}`)
              )
            )
            .limit(1);
          resolvedUserId = sources[0]?.userId ?? undefined;
        } catch {
        }
      }

      let result: { handled: boolean; message: string };
      try {
        result = await handleWebhookEvent(payload, resolvedUserId);
        await markEventProcessed(webhookDbId, result.message);
      } catch (handlerErr) {
        const errMsg = handlerErr instanceof Error ? handlerErr.message : String(handlerErr);
        await markEventFailed(webhookDbId, errMsg);
        logger.error("Fasten webhook handler error", {
          category: "webhook",
          eventType: payload.type,
          eventId,
          error: errMsg,
        });
        return res.status(500).json({ error: "Webhook processing failed" });
      }

      auditLog(req, "fasten_webhook", "webhook", eventId, {
        eventType: payload.type,
        handled: result.handled,
        apiMode: payload.api_mode,
      });

      res.status(200).json(result);
    } catch (error) {
      logger.error("Fasten webhook processing error", {
        category: "webhook",
        error: error instanceof Error ? error.message : String(error),
      });
      res.status(500).json({ error: "Webhook processing failed" });
    }
  });


