  app.post("/api/fasten/connection-event", requireAuth, async (req: Request, res: Response) => {
    try {
      const userId = getUserId(req);
      const { event, connectNonce } = req.body as any;

      if (!event) {
        return res.status(400).json({ error: "Event data is required" });
      }

      if (!connectNonce || !validateFastenNonce(connectNonce, userId)) {
        logger.warn("Fasten connection-event rejected: invalid or missing nonce", {
          category: "security",
          userId,
          eventType: event.type || "unknown",
        });
        return res.status(403).json({ error: "Invalid session token" });
      }

      logger.info("Fasten Stitch client event", {
        category: "phi_access",
        userId,
        eventType: event.type || "unknown",
        orgConnectionId: event.org_connection_id,
      });

      if (event.type === "patient.connection_success" && event.org_connection_id) {
        pendingFastenSessions.delete(userId!);

        const orgConnectionId: string = event.org_connection_id;

        const callbackVerified = isCallbackVerifiedId(orgConnectionId, userId!);
        let dbVerified = false;
        if (!callbackVerified) {
          try {
            const existingConnections = await db
              .select()
              .from(fastenConnections)
              .where(
                and(
                  eq(fastenConnections.userId, userId!),
                  eq(fastenConnections.orgConnectionId, orgConnectionId)
                )
              )
              .limit(1);
            dbVerified = existingConnections.length > 0;
          } catch {
            dbVerified = false;
          }
        }

        if (!callbackVerified && !dbVerified) {
          logger.warn("Fasten connection-event rejected: org_connection_id not server-verified", {
            category: "security",
            userId,
            orgConnectionId,
          });
          return res.status(403).json({ error: "Connection not authorized" });
        }

        if (callbackVerified) {
          fastenCallbackVerifiedIds.delete(orgConnectionId);
        }

        consumeFastenNonce(connectNonce);
        const { triggerEhiExport } = await import("../fasten-health-service");
        await triggerEhiExport(orgConnectionId);

        const { registerFastenSourceWithMetadata } = await import("../background-sync-service");
        registerFastenSourceWithMetadata(
          userId!,
          orgConnectionId,
          event.source_name || `Fasten-${orgConnectionId}`
        );

        setTimeout(async () => {
          try {
            logger.info("Auto-running deduplication after Fasten Health sync", { category: "system", userId });
            await deduplicationService.runFullScan("fasten_health_sync");
          } catch (dedupErr) {
            logger.warn("Auto-deduplication after sync failed (non-critical)", { category: "system", error: String(dedupErr) });
          }
        }, 5000);
      }

      auditLog(req, "fasten_connection_event", "data_source", event.org_connection_id || "unknown", {
        eventType: event.type,
        connectionStatus: event.connection_status,
        source: "fasten_stitch",
      });

      res.json({ received: true });
    } catch (error) {
      res.status(500).json({ error: "Failed to process connection event" });
    }
  });


  app.post("/api/fasten/store-payer-token", requireAuth, async (req: Request, res: Response) => {
    try {
      const userId = getUserId(req);
      if (!userId) return res.status(401).json({ error: "Unauthorized" });

      const ALLOWED_SOURCE_TYPES = [
        "cigna", "united", "aetna", "humana", "anthem", "kaiser",
        "epic", "quest", "labcorp", "cerner", "allscripts", "athenahealth",
        "meditech", "nextgen", "eclinicalworks", "fasten",
      ];

      const { sourceType, accessToken, refreshToken, expiresAt, fhirBaseUrl } = req.body as any;
      if (!sourceType || !accessToken) {
        return res.status(400).json({ error: "sourceType and accessToken required" });
      }
      if (!ALLOWED_SOURCE_TYPES.includes(sourceType.toLowerCase())) {
        return res.status(400).json({ error: "Invalid sourceType" });
      }

      const { isAuth0FhirBrokerConfigured, storePayerToken } = await import("../auth0-fhir-broker");
      if (!isAuth0FhirBrokerConfigured()) {
        return res.status(501).json({ error: "FHIR broker not configured" });
      }

      await storePayerToken(userId, sourceType, {
        accessToken,
        refreshToken: refreshToken || "",
        expiresAt: expiresAt || Date.now() + 3600000,
        fhirBaseUrl: fhirBaseUrl || "",
      });

      auditLog(req, "payer_token_stored", "data_source", sourceType, { userId, sourceType });
      res.json({ stored: true, sourceType });
    } catch (error: any) {
      console.error("Store payer token error:", error);
      res.status(500).json({ error: "Failed to store payer token" });
    }
  });


